mapper.select:
SELECT id, phone, balance, free_views_remaining AS freeViewsRemaining, vip_level AS vipLevel, vip_start_at AS vipStartAt, vip_expire_at AS vipExpireAt, created_at AS createdAt, updated_at AS updatedAt FROM tw_h5_user
AND phone LIKE CONCAT('%', #{q}, '%')
ORDER BY id DESC LIMIT #{offset}, #{limit}
